<script setup lang="ts">
import { ref } from "vue";
import { http } from "@/utils/http";
type Item = Record<string, any>; const tab = ref("providers"); const rows = ref<Item[]>([]); const loading = ref(false); const error = ref("");
async function load() { loading.value = true; error.value = ""; try { const result = await http.get<unknown, unknown>("/ai/models"); rows.value = Array.isArray(result) ? result as Item[] : []; } catch (e: any) { error.value = e?.response?.data?.detail || "AI 配置接口尚未接入"; } finally { loading.value = false; } }
load();
</script>
<template><main class="p-4 md:p-6"><div class="flex justify-between items-start mb-6"><div><h1 class="text-2xl font-semibold">模型与提供方</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">查看实际路由策略，Credential 永不在界面明文展示。</p></div><div class="flex gap-2"><el-button>新增提供方</el-button><el-button :loading="loading" @click="load">刷新</el-button></div></div><el-alert v-if="error" :title="error" type="warning" show-icon :closable="false" class="mb-4"/><el-tabs v-model="tab"><el-tab-pane label="提供方" name="providers"/><el-tab-pane label="模型" name="models"/><el-tab-pane label="路由" name="routing"/></el-tabs><el-card shadow="never" class="mt-4"><template v-if="tab === 'providers'"><el-empty v-if="!rows.length" description="暂无 Provider；后端 AI 配置接口接入后可在此管理"/><el-table v-else :data="rows" stripe><el-table-column prop="name" label="Provider 名称" min-width="200"/><el-table-column prop="type" label="类型" width="130"/><el-table-column prop="endpoint" label="Endpoint / Region" min-width="220"/><el-table-column prop="enabled" label="是否启用" width="110"/><el-table-column label="Credential 状态" width="150">已配置状态由服务端提供</el-table-column><el-table-column prop="health" label="健康状态" width="130"/></el-table></template><template v-else-if="tab === 'models'"><el-empty description="暂无模型发现结果；模型能力和成本元数据必须来自后端"/></template><template v-else><el-alert title="路由模拟仅接受虚拟请求属性，不会发送真实内容" type="info" show-icon/><el-form label-position="top" class="mt-5 max-w-xl"><el-form-item label="Request Class"><el-input placeholder="例如 summarization"/></el-form-item><el-form-item label="Persona / Capability"><el-input placeholder="例如 default / tool-use"/></el-form-item><el-form-item label="Privacy Class"><el-select class="w-full"><el-option label="普通" value="normal"/><el-option label="敏感" value="sensitive"/></el-select></el-form-item><el-button type="primary">模拟路由</el-button></el-form></template></el-card></main></template>
